<?php
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function url($p=''):string{global $config;return rtrim($config['base_url'],'/').'/'.ltrim($p,'/');}
function go($p):never{header('Location:'.url($p));exit;}
function csrf():string{if(empty($_SESSION['_csrf']))$_SESSION['_csrf']=bin2hex(random_bytes(32));return $_SESSION['_csrf'];}
function verify_csrf():void{if(!hash_equals(csrf(),(string)($_POST['_csrf']??''))){http_response_code(419);exit('Session expired. Reload and try again.');}}
function user(){return $_SESSION['user']??null;}
function auth():void{if(!user())go('login');}
function can(...$roles):bool{return user()&&in_array(user()['role_code'],$roles,true);}
function can_access(string $module,string $action='view'):bool{if(!user())return false;if(user()['role_code']==='ADMIN')return true;static $cache=[];$key=user()['role_id'].':'.$module;if(!array_key_exists($key,$cache)){global $pdo;$q=$pdo->prepare('SELECT can_view,can_create,can_edit,can_approve FROM role_permissions WHERE role_id=? AND module_code=?');$q->execute([user()['role_id'],$module]);$cache[$key]=$q->fetch()?:['can_view'=>0,'can_create'=>0,'can_edit'=>0,'can_approve'=>0];}$column=['view'=>'can_view','create'=>'can_create','edit'=>'can_edit','approve'=>'can_approve'][$action]??'can_view';return (bool)$cache[$key][$column];}
function require_access(string $module,string $action='view'):void{auth();if(!can_access($module,$action)){http_response_code(403);exit('Your role does not have permission to access this module or action.');}}
function role(...$roles):void{auth();if(!can(...$roles)){http_response_code(403);exit('Permission denied.');}$path=trim(parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)??'/','/');$base=trim((string)(parse_url(url(),PHP_URL_PATH)??''),'/');if($base&&str_starts_with($path,$base))$path=trim(substr($path,strlen($base)),'/');$module=match(true){$path===''||$path==='dashboard'=>'dashboard',str_starts_with($path,'requisitions')=>'procurement',in_array($path,['vendors','customers','products','offices','inventory','sales','reports','users','audit','role-access','role-master'],true)=>['role-access'=>'role_access','role-master'=>'role_master'][$path]??$path,str_starts_with($path,'invoice')=>'sales',default=>null};if($module){$action='view';if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){$action=match($module){'procurement'=>str_contains($path,'new')?'create':'approve','sales'=>'create','inventory'=>'edit','role_access'=>'edit','role_master'=>isset($_POST['id'])&&(int)$_POST['id']>0?'edit':'create',default=>isset($_GET['edit'])||isset($_POST['id'])?'edit':'create'};}require_access($module,$action);}}
function flash($s,$t='success'):void{$_SESSION['_flash']=[$s,$t];}
function audit($db,$action,$entity,$id,$details=[]):void{$q=$db->prepare('INSERT INTO audit_logs(user_id,office_id,action,entity_type,entity_id,details_json,ip_address) VALUES(?,?,?,?,?,?,?)');$q->execute([user()['id']??null,user()['office_id']??null,$action,$entity,$id,json_encode($details),$_SERVER['REMOTE_ADDR']??null]);}
function nav_active(string $target):string{$path=trim(parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)??'/','/');$base=trim((string)(parse_url(url(),PHP_URL_PATH)??''),'/');if($base&&str_starts_with($path,$base))$path=trim(substr($path,strlen($base)),'/');$path=$path?:'dashboard';if($target==='')$target='dashboard';return ($path===$target||($target!==''&&str_starts_with($path,$target.'/')))?'active':'';}
function scope():array{$u=user();$all=in_array($u['role_code'],['ADMIN','HO_MANAGER'],true);$regional=($u['office_type']??'')==='RO';return [$all||$regional?null:(int)$u['office_id'],$all?null:(int)$u['region_id']];}
function header_ui($title):void{$u=user();$f=$_SESSION['_flash']??null;unset($_SESSION['_flash']);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> · JCI JDP</title><link rel="stylesheet" href="<?=e(url('assets/app.css?v=20261120-sales-layout-2'))?>"></head><body><?php if($u):?><aside><a class="brand" href="<?=e(url())?>"><i>J</i><b>JCI<small>ENTERPRISE JDP</small></b></a><p class="label">WORKSPACE</p><nav>
<a class="<?=nav_active('')?>" href="<?=e(url())?>">▦　 Overview</a>
