<?php if(can_access('offices')):?><a class="<?=nav_active('offices')?>" href="<?=e(url('offices'))?>">⌂　 Office master</a><?php endif;?>
<?php if(can_access('users')):?><a class="<?=nav_active('users')?>" href="<?=e(url('users'))?>">♙　 User management</a><?php endif;?>
