</nav><div class="secure">●　 SECURE WORKSPACE<br><small>Organization data scoped</small></div></aside><main><header>JCI <span>/</span> <?=e($title)?><div class="profile"><b><?=e($u['name'])?></b><small><?=e($u['office_name'])?> · <?=e($u['role_name'])?></small><form method="post" action="<?=e(url('logout'))?>"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><button>Sign out ↗</button></form></div></header><section class="content"><div class="title"><div><small>JUTE CORPORATION OF INDIA LIMITED</small><h1><?=e($title)?></h1></div><?php if($title==='Procurement'&&can_access('procurement','create')):?><a class="btn" href="<?=e(url('requisitions/new'))?>">＋ New requisition</a><?php endif;?></div><?php if($f):?><p class="notice <?=e($f[1])?>"><?=e($f[0])?></p><?php endif;?><?php else:?><main class="auth"><?php endif;}
function footer_ui():void{if(user()):?></section><footer>JCI ENTERPRISE DIGITAL PLATFORM <span>INTERNAL · <?=date('Y')?></span></footer></main><?php else:?></main><?php endif;?></body></html><?php }
function layout($title,$fn):void{header_ui($title);$fn();footer_ui();}
function req_table($rows,$actions=false):void{?><div class="scroll"><table><thead><tr><th>REFERENCE / REQUEST</th><th>OFFICE</th><th>REQUESTER</th><th>ESTIMATED VALUE</th><th>STATUS / APPROVER</th><?php if($actions):?><th>ACTION</th><?php endif;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['title'])?></b><small><?=e(($r['product_sku']??'')?($r['product_sku'].' - '.($r['product_name']??'')):'')?> · JDP-PR-<?=str_pad($r['id'],5,'0',STR_PAD_LEFT)?> · <?=e(date('d M Y',strtotime($r['created_at'])))?></small></td><td><?=e($r['office_name'])?></td><td><?=e($r['requester'])?></td><td>₹ <?=number_format($r['estimated_amount'],2)?></td><td><em class="<?=e($r['status'])?>"><?=e(strtoupper($r['status']))?></em><?php if(!empty($r['approved_by_name'])):?><small><?=e($r['status']==='approved'?'Approved':'Returned')?> by <?=e($r['approved_by_name'])?> · <?=e($r['approved_at']?date('d M Y H:i',strtotime($r['approved_at'])):'')?></small><?php elseif($r['status']==='pending'):?><small>Awaiting authorized approver</small><?php endif;?></td><?php if($actions):?><td><?php if($r['status']==='pending'&&can_access('procurement','approve')&&can('ADMIN','HO_MANAGER','RO_MANAGER','APPROVER')&&(int)$r['created_by']!==(int)user()['id']):?><form class="inline" method="post"><input type="hidden" name="_csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button name="action" value="approve">Approve</button><button name="action" value="reject">Return</button></form><?php else:?>—<?php endif;?></td><?php endif;?></tr><?php endforeach;if(!$rows):?><tr><td class="empty" colspan="6">No requisitions yet. Create one to start the approval workflow.</td></tr><?php endif;?></tbody></table></div><?php }
